<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { managementProvider as api, saveDownload } from '@/services/management'
import { reportProvider } from '@/services/report'
import { useAuthStore } from '@/stores/auth'
import { accountErrors } from '@/utils/management'
import { formatBeijingTime, filingStatusLabels } from '@/utils/filing'
import { reportStatusLabels } from '@/utils/review'
import { roleNames } from '@/config/navigation'
import RegionPicker from '@/components/RegionPicker.vue'
import type { AccountFilters, AccountRow } from '@/types/management'
import type { SurveyPeriod } from '@/types/report'
import { ApiError } from '@/services/api'
const auth=useAuthStore(),filters=reactive<AccountFilters>({}),applied=ref<AccountFilters>({}),rows=ref<AccountRow[]>([]),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),errors=ref<Record<string,string>>({}),periods=ref<SurveyPeriod[]>([]),ready=ref(false)
const statuses={NO_FILING:'未备案',...filingStatusLabels}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message;if(e instanceof ApiError)errors.value=e.fieldErrors}finally{busy.value=false}}
async function query(reset=true){errors.value=reset?accountErrors(filters):{};if(Object.keys(errors.value).length)return;await run(async()=>{const q=reset?Object.fromEntries(Object.entries(filters).map(([k,v])=>[k,typeof v==='string'?v.trim():v])):applied.value;rows.value=[];total.value=0;ready.value=false;const r=await api.accounts({...q,page:reset?0:page.value-1,size:20},auth.token!);rows.value=r.data.items;total.value=r.data.total;applied.value={...q};if(reset)page.value=1;ready.value=true})}
async function clear(){for(const k of Object.keys(filters))delete filters[k as keyof AccountFilters];page.value=1;await query()}
async function exportFile(){await run(async()=>saveDownload(await api.export('accounts',applied.value,auth.token!)))}
onMounted(async()=>{await run(async()=>{periods.value=(await reportProvider.periods(auth.token!)).data.items});const periodError=error.value;await query();if(periodError)error.value=[error.value,periodError].filter(Boolean).join('；')})
</script>
<template><section><h1>全省账号查询</h1><p>数据状态指当前企业备案状态；日期指北京时间账号创建日。期次、月份和季度表示企业在该期有报表（含草稿），月份和季度按调查期开始时间计算；作废报表不匹配期次筛选。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-card v-loading="busy" shadow="never"><el-form label-position="top" :disabled="busy" class="filters"><el-form-item label="单位名称"><el-input v-model="filters.unitName" clearable/></el-form-item><el-form-item label="登录账号"><el-input v-model="filters.username" clearable/></el-form-item><el-form-item label="用户类型"><el-select v-model="filters.userType" clearable><el-option v-for="(v,k) in roleNames" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item label="所属地市"><RegionPicker v-model="filters.cityCode" any-level :select-level="2"/></el-form-item><el-form-item label="所属县区"><RegionPicker v-model="filters.countyCode" any-level :select-level="3"/></el-form-item><el-form-item label="所属区域（含下级）"><RegionPicker v-model="filters.regionCode" any-level/></el-form-item><el-form-item label="数据状态（备案）"><el-select v-model="filters.dataStatus" clearable><el-option v-for="(v,k) in statuses" :key="k" :label="v" :value="k"/></el-select></el-form-item><el-form-item label="企业性质代码"><el-input v-model="filters.natureCode" clearable placeholder="输入企业性质代码"/></el-form-item><el-form-item label="所属行业代码"><el-input v-model="filters.industryCode" clearable placeholder="输入行业代码"/></el-form-item><el-form-item label="创建起始日期"><el-date-picker v-model="filters.createdFrom" value-format="YYYY-MM-DD" type="date"/></el-form-item><el-form-item label="创建结束日期" :error="errors.createdTo"><el-date-picker v-model="filters.createdTo" value-format="YYYY-MM-DD" type="date"/></el-form-item><el-form-item label="调查期"><el-select v-model="filters.periodCode" clearable><el-option v-for="p in periods" :key="p.code" :value="p.code" :label="p.label"/></el-select></el-form-item><el-form-item label="统计月份"><el-date-picker v-model="filters.month" type="month" value-format="YYYY-MM"/></el-form-item><el-form-item label="统计季度" :error="errors.quarter"><el-input v-model="filters.quarter" placeholder="例如 2026-Q4" clearable/></el-form-item><el-form-item label="报表状态（须指定期次）" :error="errors.reportStatus"><el-select v-model="filters.reportStatus" clearable><el-option v-for="(v,k) in reportStatusLabels" :key="k" :label="v" :value="k"/></el-select></el-form-item></el-form><div class="form-actions"><el-button type="primary" :disabled="busy" @click="query()">查询</el-button><el-button :disabled="busy" @click="clear">清除条件</el-button><el-button :disabled="busy||!ready" @click="exportFile">导出全部匹配账号 Excel</el-button></div><p>导出使用当前列表已应用的条件；修改筛选后请点击查询。企业性质及行业暂按代码筛选，可从查询结果核对；当前接口未提供省级字典选项。</p><el-table :data="rows" empty-text="暂无符合条件的账号"><el-table-column prop="userId" label="账号ID"/><el-table-column prop="unitName" label="单位名称" min-width="180"/><el-table-column prop="username" label="登录账号" min-width="150"/><el-table-column label="用户类型" width="110"><template #default="s">{{roleNames[s.row.userType as keyof typeof roleNames]}}</template></el-table-column><el-table-column label="启用状态"><template #default="s">{{s.row.enabled?'启用':'停用'}}</template></el-table-column><el-table-column prop="provinceName" label="所属省"/><el-table-column prop="cityName" label="所属市"/><el-table-column prop="countyName" label="所属县区"/><el-table-column prop="regionName" label="所属区域"/><el-table-column label="备案状态" width="110"><template #default="s">{{s.row.dataStatus?statuses[s.row.dataStatus as keyof typeof statuses]:'—'}}</template></el-table-column><el-table-column label="报表状态" width="120"><template #default="s">{{s.row.reportStatus?reportStatusLabels[s.row.reportStatus as keyof typeof reportStatusLabels]:'—'}}</template></el-table-column><el-table-column prop="natureName" label="企业性质" min-width="140"/><el-table-column prop="natureCode" label="性质代码" min-width="140"/><el-table-column prop="industryName" label="行业" min-width="140"/><el-table-column prop="industryCode" label="行业代码" min-width="140"/><el-table-column label="创建时间（北京时间）" min-width="190"><template #default="s">{{formatBeijingTime(s.row.createdAt)}}</template></el-table-column></el-table><el-pagination v-model:current-page="page" :disabled="busy" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="query(false)"/></el-card></section></template>
<style scoped>.filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:0 20px}.el-select,.el-date-editor{width:100%}</style>
